// Christmas family options, shared by the customer form, the save route, the admin view and the Drive folder.
// The option list itself is generated by scripts/build-christmas-catalog.cjs.
import raw from "./catalog.json";

export type XOption = { id: string; file: string; label: string };
export type XType = "Man" | "Woman" | "Child" | "Pet";
type PersonType = Exclude<XType, "Pet">;
type Body = { label: string; file: string };
type Catalog = {
  builtAt: string;
  maxMembers: number;
  skins: { code: string; label: string; hex: string }[];
  jumpers: { adult: { code: string; label: string; thumb: string }[]; child: { code: string; label: string; thumb: string }[] };
  bodies: Record<PersonType, Record<string, Record<string, Body[]>>>;
  hair: Record<PersonType, XOption[]>;
  pets: XOption[];
};

export const xmasCatalog = raw as Catalog;
export const X_TYPES: XType[] = ["Man", "Woman", "Child", "Pet"];
export const MAX_X_MEMBERS = xmasCatalog.maxMembers;
export const xThumb = (id: string) => `/xmas/${id}.webp`;
export const CHILD_AGES = Array.from({ length: 14 }, (_, i) => i); // 0–13 (under 14)

export const EXTRAS = [
  { key: "hat", label: "Santa hat" },
  { key: "antlers", label: "Reindeer antlers" },
  { key: "bow", label: "Red hair bow" },
] as const;
export type ExtraKey = (typeof EXTRAS)[number]["key"];

export type XMember = {
  type: XType;
  name?: string;
  age?: number;          // children only
  skin?: string;         // people
  jumper?: string;       // people
  hair?: string;         // people (option id)
  pet?: string;          // pets (option id)
  extras?: ExtraKey[];
};
export type XmasSubmission = { title?: string; notes?: string; members: XMember[] };

export const isPerson = (t: XType): t is PersonType => t !== "Pet";
export const isAdult = (t: XType) => t === "Man" || t === "Woman";
export const jumpersFor = (t: XType) => (t === "Child" ? xmasCatalog.jumpers.child : xmasCatalog.jumpers.adult);
export const hairFor = (t: XType) => (isPerson(t) ? xmasCatalog.hair[t] : []);

/** Square card for up to 4 people and 1 pet; anything bigger is the A5 landscape card. */
export function printFormat(members: XMember[]): "Square card" | "A5 landscape card" {
  const pets = members.filter((m) => m.type === "Pet").length;
  return members.length - pets <= 4 && pets <= 1 ? "Square card" : "A5 landscape card";
}

/** Adults can't stand on the outside edge — when there are at least 2 children/pets, both ends must be one. */
export function edgeProblem(members: XMember[]): string | null {
  const others = members.filter((m) => !isAdult(m.type)).length;
  if (others < 2 || members.length < 2) return null;
  if (isAdult(members[0].type) || isAdult(members[members.length - 1].type)) {
    return "Adults can't go on the ends of the card. Please move a child or pet to the first and last places using the arrows.";
  }
  return null;
}

export function xMissing(m: XMember): string[] {
  const miss: string[] = [];
  if (m.type === "Pet") {
    if (!m.pet) miss.push("pet");
    return miss;
  }
  if (m.type === "Child" && !CHILD_AGES.includes(m.age as number)) miss.push("age");
  if (!m.skin) miss.push("skin tone");
  if (!m.jumper) miss.push("jumper colour");
  if (!m.hair) miss.push("hair");
  return miss;
}

export function validXMember(m: XMember): boolean {
  if (!X_TYPES.includes(m.type)) return false;
  if (m.extras && !m.extras.every((e) => EXTRAS.some((x) => x.key === e))) return false;
  if (m.type === "Pet") return !!m.pet && xmasCatalog.pets.some((p) => p.id === m.pet);
  if (m.skin && !xmasCatalog.skins.some((s) => s.code === m.skin)) return false;
  if (m.jumper && !jumpersFor(m.type).some((j) => j.code === m.jumper)) return false;
  if (m.hair && !hairFor(m.type).some((h) => h.id === m.hair)) return false;
  return xMissing(m).length === 0;
}

export type ResolvedXPart = { part: string; label: string; file: string; thumbId?: string };
export type ResolvedXMember = { position: number; who: string; summary: string; extras: string[]; parts: ResolvedXPart[] };

/** Turn picks into exact Drive files (adults get all 3 poses, children all 3 bodies — we choose which to use). */
export function resolveXmas(sub: XmasSubmission): ResolvedXMember[] {
  return sub.members.map((m, i) => {
    const name = m.name?.trim();
    const age = m.type === "Child" && m.age != null ? ` aged ${m.age}` : "";
    const who = `${m.type}${age}${name ? ` (${name})` : ""}`;
    const extras = (m.extras ?? []).map((k) => EXTRAS.find((e) => e.key === k)?.label ?? k);
    const parts: ResolvedXPart[] = [];
    let summary: string;
    if (m.type === "Pet") {
      const pet = xmasCatalog.pets.find((p) => p.id === m.pet);
      if (pet) parts.push({ part: "Pet", label: pet.label, file: pet.file, thumbId: pet.id });
      summary = pet?.label ?? "pet";
    } else {
      const skin = xmasCatalog.skins.find((s) => s.code === m.skin);
      const jumper = jumpersFor(m.type).find((j) => j.code === m.jumper);
      const hair = hairFor(m.type).find((h) => h.id === m.hair);
      for (const b of xmasCatalog.bodies[m.type][m.skin ?? ""]?.[m.jumper ?? ""] ?? []) {
        parts.push({ part: "Body", label: `${jumper?.label ?? ""} jumper, ${b.label}`, file: b.file, thumbId: jumper?.thumb });
      }
      if (hair) parts.push({ part: "Hair", label: hair.label, file: hair.file, thumbId: hair.id });
      summary = [skin && `${skin.label.toLowerCase()} skin`, jumper && `${jumper.label.toLowerCase()} jumper`, hair && `hair ${hair.label}`]
        .filter(Boolean).join(", ");
    }
    return { position: i + 1, who, summary, extras, parts };
  });
}

/** Plain-text version for the log and the notification email. */
export function xmasText(sub: XmasSubmission): string {
  const lines = resolveXmas(sub).map((r) => `${r.position}. ${r.who}: ${r.summary}${r.extras.length ? ` + ${r.extras.join(", ")}` : ""}`);
  return [
    sub.title ? `Family name: ${sub.title}` : null,
    `${sub.members.length} people & pets — ${printFormat(sub.members)}`,
    ...lines,
    sub.notes ? `Notes: ${sub.notes}` : null,
  ].filter(Boolean).join("\n");
}
